CREATE TABLE "work_collaborations" (
	"id" uuid PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"event_id" uuid NOT NULL,
	"work_id" uuid NOT NULL,
	"owner_id" uuid NOT NULL,
	"author_id" uuid NOT NULL,
	"email" text NOT NULL,
	"person_id" uuid,
	"token_hash" text NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"accepted_at" timestamp with time zone,
	CONSTRAINT "work_collaborations_token_hash_unique" UNIQUE("token_hash"),
	CONSTRAINT "work_collaboration_status" CHECK ("work_collaborations"."status" IN ('pending','accepted','revoked')),
	CONSTRAINT "work_collaboration_dates" CHECK ("work_collaborations"."expires_at">"work_collaborations"."created_at"),
	CONSTRAINT "work_collaboration_acceptance" CHECK ("work_collaborations"."status"<>'accepted' OR ("work_collaborations"."person_id" IS NOT NULL AND "work_collaborations"."accepted_at" IS NOT NULL))
);
